class Cat {
    static final int MAX_FISH = 3;
    String name;

    Cat(String name) {
        this.name = name;
    }

    void eat(int fish) {
        if (fish > MAX_FISH) {
            System.out.println(name + "：太多啦");
        } else {
            System.out.println(name + "：处理了 " + fish + " 条");
        }
    }
}

public class Main {
    public static void main(String[] args) {
        Cat a = new Cat("张三");
        a.eat(2);
        a.eat(5);
        System.out.println("上限是 " + Cat.MAX_FISH);
    }
}
